package com.wedo.backend.task.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="task_status_history") public class TaskStatusHistoryEntity { @Id private UUID id; @Column(name="task_id",nullable=false) private UUID taskId; @Enumerated(EnumType.STRING) @Column(name="from_status") private TaskStatus fromStatus; @Enumerated(EnumType.STRING) @Column(name="to_status",nullable=false) private TaskStatus toStatus; @Column(name="changed_by") private UUID changedBy; @Column(name="created_at",nullable=false) private Instant createdAt; protected TaskStatusHistoryEntity(){} public TaskStatusHistoryEntity(UUID id,UUID taskId,TaskStatus from,TaskStatus to,UUID actor,Instant at){this.id=id;this.taskId=taskId;this.fromStatus=from;this.toStatus=to;this.changedBy=actor;this.createdAt=at;} public TaskStatus getFromStatus(){return fromStatus;} public TaskStatus getToStatus(){return toStatus;} public UUID getChangedBy(){return changedBy;} public Instant getCreatedAt(){return createdAt;} }
